import { useMemo, useState } from 'react';
import { JxTable, JxBadge, JxPagination, JxEmptyState } from '@jinx-ui/react';

interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: { users: User[] }) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const visible = useMemo(
    () => users.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE),
    [users, safePage],
  );

  if (users.length === 0) {
    return (
      <JxEmptyState
        title="Пользователей пока нет"
        message="Пригласите участников, и они появятся в этом списке."
      />
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <JxTable>
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'default'} dot>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>
      {pageCount > 1 && (
        <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
      )}
    </div>
  );
}

